import{_ as a,o,c as l,a2 as i}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"1.3 电工的职责与职业道德","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-3-dian-gong-de-zhi-ze-yu-zhi-ye-dao-de.md","filePath":"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-3-dian-gong-de-zhi-ze-yu-zhi-ye-dao-de.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/01-chapter-1-an-quan-sheng-chan-fa-l-fa-gui/1-3-dian-gong-de-zhi-ze-yu-zhi-ye-dao-de.md"};function e(n,t,s,d,u,h){return o(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="_1-3-电工的职责与职业道德" tabindex="-1">1.3 电工的职责与职业道德 <a class="header-anchor" href="#_1-3-电工的职责与职业道德" aria-label="Permalink to &quot;1.3 电工的职责与职业道德&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>证书是&quot;资格&quot;,职责和职业道德是&quot;态度&quot;。考试不会只考你会不会接线,还会考你<strong>该不该这么干</strong>——比如能不能带电作业、发现隐患怎么办、能不能图省事。这一节帮你建立正确的&quot;电工三观&quot;。</p><h2 id="一、低压电工的岗位职责" tabindex="-1">一、低压电工的岗位职责 <a class="header-anchor" href="#一、低压电工的岗位职责" aria-label="Permalink to &quot;一、低压电工的岗位职责&quot;">​</a></h2><p>作为一名低压电工,职责概括起来就是:<strong>安全、规范、及时</strong>地完成低压电气设备的安装、运行、检修和维护。</p><p>具体包括:</p><ol><li><strong>负责低压电气设备与线路的安装、调试、维修与保养</strong>(如配电箱、电动机、照明线路、控制线路等);</li><li><strong>严格执行安全操作规程</strong>,遵守停送电制度和作业票制度,不违章作业;</li><li><strong>发现设备异常和安全隐患,及时处理或上报</strong>,绝不&quot;带病运行&quot;;</li><li>正确使用和保管电工工具、仪表和安全用具;</li><li>参与安全检查和电气设备预防性试验;</li><li>发生触电、电气火灾等事故时,<strong>先救人、先断电</strong>,正确处理现场。</li></ol><h2 id="二、职业道德的主要内容" tabindex="-1">二、职业道德的主要内容 <a class="header-anchor" href="#二、职业道德的主要内容" aria-label="Permalink to &quot;二、职业道德的主要内容&quot;">​</a></h2><p>电工的职业道德,核心是&quot;<strong>安全第一,生命至上</strong>&quot;,具体体现在:</p><table tabindex="0"><thead><tr><th>职业道德要求</th><th>通俗解释</th></tr></thead><tbody><tr><td>遵纪守法、持证上岗</td><td>不无证作业,不违反规程</td></tr><tr><td>爱岗敬业、忠于职守</td><td>干一行爱一行,认真负责</td></tr><tr><td>安全第一、预防为主</td><td>宁可多查一遍,不冒一次险</td></tr><tr><td>诚实守信、实事求是</td><td>不虚报数据、不隐瞒故障、不偷工减料</td></tr><tr><td>团结协作、文明施工</td><td>与同事、监护人配合好,作业现场整洁</td></tr><tr><td>钻研业务、精益求精</td><td>不断学习,提高技术水平</td></tr></tbody></table><h2 id="三、工作纪律与-红线-行为" tabindex="-1">三、工作纪律与&quot;红线&quot;行为 <a class="header-anchor" href="#三、工作纪律与-红线-行为" aria-label="Permalink to &quot;三、工作纪律与&quot;红线&quot;行为&quot;">​</a></h2><p>以下行为是电工的&quot;红线&quot;,碰了就可能出人命或担责任:</p><ul><li>❌ <strong>无证作业、超范围作业</strong>;</li><li>❌ <strong>不执行停电、验电、挂接地线</strong>程序就干活;</li><li>❌ <strong>带电检修</strong>(除非是经过批准的带电作业并有完善防护);</li><li>❌ 不按规定穿戴绝缘手套、绝缘鞋等防护用品;</li><li>❌ 酒后作业、疲劳作业;</li><li>❌ 用湿手操作电气设备、乱拉乱接电线;</li><li>❌ 发现隐患不处理、不上报,&quot;事不关己&quot;心态。</li></ul><blockquote><p>💡 考试里出现&quot;电工为了赶进度可以不验电直接干活&quot;这类说法,<strong>一律判断为错误</strong>。</p></blockquote><h2 id="四、正确的工作态度示例" tabindex="-1">四、正确的工作态度示例 <a class="header-anchor" href="#四、正确的工作态度示例" aria-label="Permalink to &quot;四、正确的工作态度示例&quot;">​</a></h2><ul><li><strong>作业前</strong>:检查工器具、确认停电、验电、挂地线、设标示牌;</li><li><strong>作业中</strong>:一人操作、一人监护,不凭经验蛮干;</li><li><strong>作业后</strong>:清点工具、恢复送电、记录归档;</li><li><strong>平时</strong>:主动参加安全培训,学习新技术、新规程。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 判断题常考:发现安全隐患应该<strong>立即处理或上报</strong>,不能拖延、隐瞒。</li><li>✅ 电工必须<strong>持证上岗、按规程操作</strong>。</li><li>⚠️ 易混点:带电作业不是&quot;绝对禁止&quot;,而是必须<strong>经批准并有可靠防护措施</strong>才可进行。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>电工职责 = 安全、规范地完成电气设备安装、检修与维护。</li><li>职业道德核心 = <strong>安全第一、生命至上</strong>,诚实守信、遵纪守法。</li><li>牢记&quot;红线&quot;行为,考试遇到这类描述一律判错。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)电工在作业中发现设备有安全隐患,可以等下班后再处理。( )</li><li>(判断)为了赶工期,低压电工可以不执行验电程序直接开始检修。( )</li><li>(判断)带电作业只有在经过批准并采取可靠安全措施的条件下才能进行。( )</li><li>(判断)电工应当持证上岗,并严格执行安全操作规程。( )</li><li>(多选)下列属于电工&quot;红线&quot;行为的有()。 A. 无证作业　B. 带电检修　C. 作业前验电　D. 酒后作业</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>×</strong>。发现隐患应立即处理或上报,不能拖延。</li><li><strong>×</strong>。停电、验电、挂接地线是检修的必经程序,不能省略。</li><li><strong>√</strong>。带电作业并非绝对禁止,但必须经过批准并采取可靠防护措施。</li><li><strong>√</strong>。持证上岗、按规程操作是基本要求。</li><li><strong>ABD</strong>。无证作业、带电检修(未经批准)、酒后作业都属于红线行为;作业前验电是正确操作。</li></ol></details>',23)])])}const q=a(r,[["render",e]]);export{c as __pageData,q as default};
